def find_Nth_Digit(numerator, denominator, nth_digit):
  # Convert the numerator and denominator to strings
  num_str = str(numerator)
  denom_str = str(denominator)

  # Find the length of the numerator and denominator
  num_len = len(num_str)
  denom_len = len(denom_str)

  # Calculate the position of the nth digit in the proper fraction
  pos = nth_digit - 1

  # If the position is less than the length of the numerator, return the digit at that position
  if pos < num_len:
    return int(num_str[pos])

  # Otherwise, calculate the position of the nth digit in the denominator
  pos -= num_len

  # If the position is less than the length of the denominator, return the digit at that position
  if pos < denom_len:
    return int(denom_str[pos])

  # Otherwise, return the remainder when the numerator is divided by the denominator
  return int(num_str[num_len + pos]) % int(denom_str[num_len + pos])

